MAKE CODE: Blink LED without delay
language arduino

// Blink LED on pin 13 every 0.5 seconds using millis()
void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  millis();
  digitalWrite(LED_BUILTIN, HIGH);
  delay(500);
  digitalWrite(LED_BUILTIN, LOW);
  delay(500);
}
END

